def _is_221(seq):
    # Every maximal run of equal values must have length equal to its value.
    i = 0
    m = len(seq)
    while i < m:
        j = i
        while j + 1 < m and seq[j + 1] == seq[i]:
            j += 1
        if j - i + 1 != seq[i]:
            return False
        i = j + 1
    return True


