def _solve(H, W, rows):
    # BFS over states (row, col, last_move_direction or None).
    # Constraint is on the cell Takahashi currently occupies:
    #   'o': next move must equal the last move (entering direction)
    #   'x': next move must differ from the last move
    #   others (., S, G): free. The start cell has no previous move.
    sr = sc = gr = gc = -1
    for i in range(H):
        for j in range(W):
            if rows[i][j] == 'S':
                sr, sc = i, j
            elif rows[i][j] == 'G':
                gr, gc = i, j
    start = (sr, sc, None)
    parent = {start: None}
    q = deque([start])
    goal_state = None
    while q:
        st_ = q.popleft()
        r, c, d = st_
        if (r, c) == (gr, gc) and st_ != start:
            goal_state = st_
            break
        cell = rows[r][c]
        for e, (dr, dc) in _DIRS.items():
            if d is not None:
                if cell == 'o' and e != d:
                    continue
                if cell == 'x' and e == d:
                    continue
            nr, nc = r + dr, c + dc
            if not (0 <= nr < H and 0 <= nc < W):
                continue
            if rows[nr][nc] == '#':
                continue
            ns = (nr, nc, e)
            if ns not in parent:
                parent[ns] = (st_, e)
                q.append(ns)
