def _reachable(start, limit):
    # BFS over all strings reachable from start, never exceeding length `limit`.
    seen = {start}
    dq = deque([start])
    while dq:
        cur = dq.popleft()
        for nb in _neighbors(cur):
            if len(nb) <= limit and nb not in seen:
                seen.add(nb)
                dq.append(nb)
    return seen


